INSERT INTO `animals_animal` VALUES (1,'Anas platyrhynchos domesticus','Качка Абакотський Ренджер','Птахи','Anas','Anatidae','Середній','Селезень: 3 кг, Качка: 2.5 кг','6–8 років','Європа, особливо Німеччина та Великобританія','Всеїдні','Висока несучість (180–200 яєць/рік), доброзичливий характер','Просторі загони з низькою огорожею, захист від хижаків','Природним шляхом або інкубатор','М\'ясо та яйця','https://agromega.in.ua/imgproxy/NYC-dXWfzJ_tGiGiWzE7AfKDfy59tNfYbXEOLBQFrbM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9hYmFjb3RfcmFuZ2VyLmpwZw.webp','Качки породи Стренджер були популярними як для м\'ясного так і яєчного напрямів. Abacot Rangers - несуть досить великі білі яйця (розміром з яйце індійського бігуна) вагою від 60 до 70 г.  За рік одна качка в середгьому зносить від 180 до 200 яєць. Качки даної породи - доброзичливі, які можуть стати ручними при постійному догляді.',1),(2,'Anas platyrhynchos domesticus','Качка Австралійська Плямиста','Птахи','Anas','Anatidae','Середній','2.5-3.0 кг','8-12 років','Австралія','Всеїдні','Плямисте оперення, висока несучість до 200 яєць на рік','Вільний вигул у загоні з доступом до води','Природним шляхом або інкубаторами','Яйця, м\'ясо','https://agromega.in.ua/imgproxy/kDrU3MLBcPGhqp05JQ6ANUzGdRyRZzhTtIaWU89zwa0/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9hdXN0cmFsaWFuX3Nwb3R0ZWRfZHVjay5qcGc.webp','Австралійська Плямиста качка - порода качок бентам. Тіло має форму краплі, а ноги розташовані в центрі. Така форма тіла та розміщення ніг зробили положення тіла майже горизонтальним. Качки мають овальні та помірно обтічні голови без виразно високого чола та пухких щік качки. У них на шиї біле коло. Груди та боки тіла Австралійської Плямистої качки мають глибокий бордовий колір. А центр грудей, що простягається під тілом, білий. Крила у них темно-сірувато-коричневі, а середина плечей і спини - темно-сірі. Їх хвіст світло-сірого кольору, а хвостовий підслідок чорний. У австралійських плямистих качок є зеленувато-жовті та карі очі. Її гомілки і ступні мають помаранчевий колір. В середньому качки зазвичай виробляють від 50 до 125 яєць на рік. Їх яйця кремового, синього або зеленого кольору.',1),(3,'Anas platyrhynchos domesticus','Качка Алабіо','Птахи','Anas','Anatidae','Середній','3.0-3.5 кг','8-12 років','Індонезія','Всеїдні','Висока продуктивність м\'яса та яєць, стійкість до захворювань','Забезпечення доступу до води, просторі загони','Природним шляхом або інкубаторами','Яйця, м\'ясо','https://agromega.in.ua/imgproxy/c_IcSTfEBbrOYciUx7wVOHZGnUQxfsgbnZor0wtoPVg/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9hbGFiaW8ucG5n.webp',' Качка Алабіо - незвичайна порода, дуже популярна в Індонезії, але рідкісна в інших місцях. Качки даної породи є дуже хорошими несучками, відкладаючи 200-250 яєць на рік (або навіть більше), і вони також часто використовуються для м\'яса. Птахи можуть добре літають, та дуже  витривалі до високих температур, як можна очікувати, що надходять з такої гарячої зони. Алабіо мають вертикальне положення тулуба, схоже на Індійського бігуна. Дзьоб та ноги жовті. Зараз важко знайти чистопородних птахів, через неконтрольоване схрещування місцевими фермерами для досягнення вищої продуктивності.',1),(4,'Anas platyrhynchos domesticus','Качка Альєр','Птахи','Anas','Anatidae','Великий','3.5-4.0 кг','6-8 років','Франція','Всеїдні','М\'ясна продуктивність, швидкий набір ваги','Доступ до водоймищ, просторий вигул','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/TKRL0oi0e2sKYOe00dDA7vMVFTO9f9Mpr3cu_TJxGvM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9PMFlONDA0LmpwZw.webp','Качка Альєр родом з Бурбона у Франції. Качки є витривалими, але вважають, що вони швидкорослі. Пір\'я у качок біле, тоді як хвостики, дзьоб і ступні оранжеві. Самка Альєр несеться раніше, ніж інші породи, і яйця важать близько 80 грам. Більшість людей тримають їх через гарне пір’я, вони гарні несучки, а їх м\'ясо смачне. Дорослий самець породи Альєр називається - селезень, а доросла самка називається - куркою. Селезні - це качки яскравішого кольору, тоді як самка (курка) зазвичай звичайного кольору для приховування, щоб вони замаскувалися від ворогів, коли вони сидять у своїх гніздах.',1),(5,'Anas platyrhynchos domesticus','Качка Анконська','Птахи','Anas','Anatidae','Середній','2.5-3.0 кг','6-7 років','Європа, США','Всеїдні','Плямисте чорно-біле оперення, висока несучість','Доступ до води, регулярне годування','Інкубатори або природним шляхом','Яйця, декоративне використання','https://agromega.in.ua/imgproxy/atHpVS1FnfRKSwaiQpn2dYv8bj6HiouEfM_UmdTdDRM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9hbmNvbmFEdWNrLmpwZw.webp','Качка Анкона - це велика м\'ясо-яєчна порода качок, яка красива, доброзичлива, прекрасна в нагулі, і останнім часом переживає сплеск популярності. Колір оперення з випадковими кольоровими плямами, які зазвичай або чорні, блакитні, шоколадні, бузкові, срібні або лавандові, причому найчастіше чорно-білі. Їхні ноги помаранчеві, а дзьоб жовтий, часто покриті плямами і темними плямами. Анкони є відмінними несучками, що зносять 210-280 великих синіх, зелених, сірих, кремових або білих яєць на рік. Анкони гарні птахи для м\'яса, тому що вони ростуть швидко та мають м\'ясо не таке жирне як м\'ясо Пекінських качок.',1),(6,'Anas platyrhynchos domesticus','Качка Африканська Чорна','Птахи','Anas','Anatidae','Великий','4.0-5.0 кг','8-10 років','Африка','Всеїдні','Темне оперення, велика вага, м\'ясна порода','Просторі водоймища, регулярне годування','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/fYIoO623gGxAkR2zgUlglQnEJJ8jL99XCP2-9Qk0pog/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9hZnJpY2FuX2JsYWNrX2R1Y2sxLmpwZw.webp','Африканська Чорна качка часто відвідує лісисті ріки та віддалені скельні басейни в гірських районах. Африканська Чорна качка має чорно-коричневе оперення, що надає птаху свою назву. Проте кілька білих смуг і синьо-зеленого дзеркала контрастують з загальним темним зовнішнім виглядом. Дорослі особини африканської чорної качки номінованої раси мають темно-соєво-коричневе до чорного оперення, загальне з забороненими білими лопатками, та цятками на крилах. Синьо-зелений дзеркало помітно в польоті. Він обрамлений чорно-білим зверху та знизу. Досить довгий хвіст показує дві вузькі білі смуги, утворені двома рядами білих плям.\nНа нижній частині живота черевце коричневе і злегка плямисте.',1),(7,'Anas platyrhynchos domesticus','Качка Балійська','Птахи','Anas','Anatidae','Середній','2.5-3.0 кг','6-8 років','Індонезія, острів Балі','Всеїдні','Декоративний вигляд, унікальне оперення','Вільний вигул з доступом до води','Природним шляхом або інкубаторами','Декоративне використання, яйця','https://agromega.in.ua/imgproxy/UGh8h0wNKQdgo_fE1pl0Fs_OLPcPqrkOBcGuBXyyMew/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy85NGFmNTEwOGFiYjIyZTUxMDM5MWMxMjczOWMxY2FiOC5qcGc.webp','Качка породи Балійська - прекрасна, легка порода домашніх качок. Вона також відома як качка Чубатий Бігун (Crested Runner) або Балійська Чубата качка, і одна з найдавніших домашніх порід качок. Балійська качка - дуже практична птиця для утримання, незважаючи на прекрасний зовнішній вигляд. Вони є чудовими мисливцями і потребують великого простору для прогулянки. Як і качки індійського бігуна, качки Балі також є прекрасним контролером шкідників для садів. Балійські качки - хороші яєчні шари. В середньому качка відкладає приблизно від 120 до 250 великих яєць на рік. Їх яйця мають від синьо-зеленого до білого кольору. Вони доброзичливі за своєю природою і зазвичай дуже хороші як домашні тварини. Вони є рідкісними за межами рідного місця, і вони не досягли такого ж успіху, як качки індійських бігунів.',1),(8,'Anas platyrhynchos domesticus','Качка Білл Хук','Птахи','Anas','Anatidae','Середній','2.5-3.0 кг','6-7 років','Європа','Всеїдні','Висока несучість, доброзичливий характер','Забезпечення водоймищ та вигулу','Інкубатори або природним шляхом','Яйця, декоративне використання','https://agromega.in.ua/imgproxy/BF07SFBb8egTlH04QAZVD8NasuBsCmS_4tbnNGPj6Hk/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9QRU8wNTRfMTBfS3J1bW1zY2huYWJlbGVudGVuLmpwZw.webp','Качка Білл Хук - це легка порода домашніх качок. Вона характеризується вигнутим дзьобом вниз, що відрізняє його від інших домашніх порід качок. Цей унікальний зовнішній вигляд зробив породу бажаною як декоративних птахів сьогодні. Але раніше вони були відомими відмінними шарами яєць. Качки Білл Хук пов\'язані з гусями та лебедями, але більш дрібні з короткими крилами, шиєю та кремезним тілом. Існує багато різновидів кольорів цієї породи качок. Смуглявий (або темний) Білл Хук у відтінках сіро-коричневого. Сорт Біло-ребриста схожий на Дюскі, але має великий наліт білого кольору на передній частині та первинному пір\'ї. Качка Білл Хук - це сезонний яєчний шар великих синіх яєць. І вони відкладають близько 100 до 200 яєць на рік.',1),(9,'Anas platyrhynchos domesticus','Качка Валлійський Арлекін','Птахи','Anas','Anatidae','Середній','2.3-2.8 кг','6-8 років','Уельс, Великобританія','Всеїдні','Декоративний окрас, висока несучість','Вигул у просторих загонах, водоймища','Інкубатори або природним шляхом','Яйця, м\'ясо, декоративне використання','https://agromega.in.ua/imgproxy/H5jo45v47u6ziNfPZtj5LpyMnHJw90W8bNLKuGsG0bU/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy93ZWxzaC1oYXJsZXF1aW4tZHVja2xpbmdzLmpwZw.webp','Американська асоціація птихівництва качка Валлійський Арлекін класифікується як легка порода качок. Порода добре відома своєю хорошою здатністю до відкладання яєць, а також своїм яскравим оперенням. Качки Валлійський Арлекін мають відносно довгі тіла, округлі груди, помірно повний живіт, середня ширина спини і широкі розставлені ноги. Їх шиї увінчані обробкою. У них овальні голови, які мають середні довгі та трохи увігнуті дзьоби. Хвіст селезнів чорнувато / бронзово оброблений білим кольором. Ноги і стопи їх помаранчеві, а нігті - коричнево-чорні. Вони можуть відкладати до 250 яєць на рік.',1),(10,'Anas platyrhynchos domesticus','Качка Ворст','Птахи','Anas','Anatidae','Середній','3.0-3.5 кг','7-8 років','Нідерланди','Всеїдні','Швидкий набір ваги, витривалість','Просторі загони з водоймами','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/NSI7FxcQlZuuUvnjTcYRqSwyXsW_rVBw5QDbjWzTdDY/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9FZW5kVmFuVm9yc3QuanBn.webp','Качка Ворст (Eend van Vorst) була експонатом серед бельгійських порід качок. De Eend van Vorst - це качка з гарним м\'ясом та яйцекладкою. Дзьоб повинен бути шиферно-блакитним, а ноги - максимально темними, бажано з темними ластами. Найбільш ефектна кольорова гама, без сумніву, синьо-попеляста: суцільно-попелясті блакитні пір’я з чорним подолом на кожному пір\'ї, без білої або жовтої плями. Окрім блакитного оперення, качка з Ворста визнана також у таких кольорах: синій, перлово-сірий, коричневий, чорний та білий.',1),(11,'Anas platyrhynchos domesticus','Качка Індійський бігун','Птахи','Anas','Anatidae','60-70 см','1.8-2.2 кг','5-7 років','Азія, Індія','Всеїдні','Незвичайна постава, висока несучість до 250 яєць на рік','Вигул на відкритих територіях, доступ до водойм','Природним шляхом або інкубаторами','Яйця, М\'ясо','https://agromega.in.ua/imgproxy/SO3G-ACKfWE2ldi_9-yFvDkMgVa3SE1zds-cQPYnin8/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9pbmRpX2JlZ3Vub2suanBn.webp','Порода качок Індійський Бігун характеризується прямою, вертикальною постановкою тіла, довгими ногами, довгою шиєю, завдяки чому вміють швидко пересуватися (не дарма ж «бігунами» назвали). Забарвлення пір\'я може бути абсолютно різним - чорний, білий, коричневий, кольору форелі, з малюнком диких качок, коричнево-крапчастий і т.д.  Індійські Бігуни без постійного доступу до води різко знижують продуктивність. Ідеальний варіант для них - можливість вільного вигулу з водоймою. Це рухлива, неслухняна порода домашніх качок, здатна знищити город, якщо ви забудете закрити хвіртку. Взимку Індійські Бігуни в наших краях потребують додаткового утеплення - тільки так вони зможуть радувати вас яйцями круглий рік. За рік самка Індійського Бігуна може знести до 350 яєць, але, як правило, обмежується двома сотнями. Птах несе яйця круглий рік, вони дуже схожі на курячі.',1),(12,'Anas platyrhynchos domesticus','Качка Гуттегемзе','Птахи','Anas','Anatidae','55-65 см','2.5-3.0 кг','6-8 років','Нідерланди, Бельгія','Всеїдні','Міцна будова тіла, універсальна продуктивність','Просторі загони, водоймища','Інкубатори або природним шляхом','М\'ясо, яйця','https://agromega.in.ua/imgproxy/jroBEliikWhwXwfifXMR9QB9E08EHgA_-TrLN7gWx7A/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9IdXR0ZWdlbXNlRHVjay5qcGc.webp','Качка Гуттегемзе або Оденанарсе (Huttegemse eend) - качка, яку в кінці 19 століття тримали набагато більше на берегах Шельди, на той час болота, ніж зараз. Ці птахи в основному були розведені в районі Оденаарде, а Хуттегем був центром качкової промисловості. Шия, груди та великі пір’я у цього стандарту білі, решта оперення синє або чорне. Крім того, потрібен спеціальний малюнок для голови, коли біла шпора біжить навколо очей від шиї. Дзьоб свинцево-блакитний, а ноги - світло-оранжево-червоні з іноді чорними плямами.',1),(13,'Anas platyrhynchos domesticus','Качка Дендермонд','Птахи','Anas','Anatidae','60-65 см','3.0-3.5 кг','7-8 років','Бельгія','Всеїдні','Велика вага, висока м\'ясна продуктивність','Просторі загони, регулярний доступ до води','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/YfC8kxr8taOkSI4CAgGzY8goiH45SSMOK8VpTtpBFXA/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9EZW5kZXJtb25kc2VFZW5kLmpwZw.webp','Качка Дендермонд регулярно спливає в історії інших бельгійський рідних порід качок. Синій колір був типовим для цієї породи, але не всі джерела погоджуються щодо наявності білої смуги або нагрудного знака. Сьогодні качку з Дендермонда впізнають лише у синьому або чорному кольорі з білим нагрудним знаком та білим пір’ям.\nЦе також великий та високий птах з типовою формою човна. На жаль, ми дуже рідко зустрічаємо цю прекрасну качку на виставках, і все ще мало заводчиків породи що колись була засновником бельгійських порід качок.',1),(14,'Anas platyrhynchos domesticus','Качка Дюклер','Птахи','Anas','Anatidae','55-60 см','3.0-3.2 кг','6-8 років','Франція','Всеїдні','М\'ясна порода, швидкий набір ваги','Доступ до води, регулярне годування','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/media/images/thumb/200/black_white_duck.webp','Качки Дюклер відносяться до середньої величини породи качок. Існує два кольорові різновиди качки Дюклер - чорне і синє. Обидва різновиди мають на кожному крилі білу серединку та одинарне біле перо. Деякі фермери описували качку Дюклера як \"класичний манжетний Крижень\", яка має зелену голову та білий нагрудник. І чорне, суцільне коричневе або навіть синє тіло сірого кольору. Він підходить як для виробництва м\'яса, так і для яєць. Порода вважається відмінним вибором для смаженої качки. У качок Дюклер досить хороші шари великих яєць. Їх яйця синювато-зеленого кольору і вони виробляють приблизно від 80 до 100 яєць на рік. ',1),(15,'Anas platyrhynchos domesticus','Качка Ейлсбері','Птахи','Anas','Anatidae','60-65 см','4.0-5.0 кг','7-9 років','Великобританія','Всеїдні','Велика вага, біле оперення, висока м\'ясна продуктивність','Просторі загони з водоймами, регулярний догляд','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/nWq7jXoRLB6Nm2dmCOEkPoWQcXsLz6GhLvfPSvfvKrk/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9heWxlc2J1cnlfZHVja3MuanBn.webp','Качка Ейлсбері (Aylesbury) з\'явилась на початку 18 століття у містечку Ейлсбері в Бакінгемширі, Англія, де стала прибутковою котеджною промисловістю, що забезпечує потреби лондонських ринків. Ейлсбері була популярна своїм м\'ясом як столова качка в столиці завдяки своїй білій тушці. Пір’я Айлсбері широко використовували в ковдрах та підстилках. Більшість людей віддавали перевагу білим качкам. Качки даної породи несуть 40 - 120 яєць на рік.',1),(16,'Anas platyrhynchos domesticus','Качка Елізабет','Птахи','Anas','Anatidae','50-55 см','2.0-2.5 кг','5-7 років','Австралія','Всеїдні','Компактна будова, висока несучість до 150 яєць на рік','Вигул у просторих загонах, доступ до водойм','Інкубатори або природним шляхом','Яйця, М\'ясо','https://agromega.in.ua/imgproxy/-2Es1x-qAz3Y3P57suUC1CSyAv_aFNsBIcVppWvM8fU/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9lbGl6YWJldGhfZHVja19WV0FfbGlnaHRfMjAxNC5qcGc.webp','Качка Єлизавета - дуже красива порода м\'ясних качок невеликого розміру. Качки Єлизавети бувають лише одного кольору і вони короткі з широкою грудною клітиною і круглими грудьми. Вони мають округлу голову і трохи короткі ноги. Селезні Елізабет має глянсову зелену голову, яка закінчується білим кільцем. У них грудне пір\'я бордового кольору і обрамовані кремовим, білим підшерстям. На спині селезні мають вугільне сіре пір’я, оббите білим кольором. У них міцний задній хребет і тьмяний чорно-коричневий хвіст. Качка Єлизавета була створена як невелика, швидко зростаюча м\'ясна порода качок. Це також непогана порода качок, що відкладають яйця.',1),(17,'Anas platyrhynchos domesticus','Качка Золотий Каскад','Птахи','Anas','Anatidae','55-60 см','3.0-3.5 кг','6-8 років','США','Всеїдні','Золотисте оперення, висока несучість до 200 яєць на рік','Доступ до водойм, регулярний вигул','Інкубатори або природним шляхом','Яйця, М\'ясо','https://agromega.in.ua/imgproxy/lQsT7yu2cNFm_HIjnQLP8Yqlj6DTUT6wsBg9edMu0Hc/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9HQ2dyb3VwLmpwZWc.webp','Качка Золотий Каскад - це домашня порода качки середньої ваги. Вони відомі червоним відтінком, помітним на голові. Селезні мають атласні зелені або бронзові голови та жовті дзьоби. Груди у них червонуваті і мають білі підщепи. Селезні на шиях мають біле кільце. Золота Каскадна качка - активна і швидкозростаюча порода качок. Це хороший яєчний шар, а також хороша м\'ясна порода качок. Зазвичай качки добре відкладають з січня по серпень. Потім перерву кілька тижнів і почнуть знову до кінця сезону. Весняні каченята часто почнуть відкладати яйця восени. Вони гарні як птахи на задньому дворі, а також хороші домашніх тварини.',1),(18,'Anas platyrhynchos domesticus','Качка Каюга','Птахи','Anas','Anatidae','55-60 см','3.0-3.5 кг','7-8 років','США, Нью-Йорк','Всеїдні','Чорне блискуче оперення, висока м\'ясна продуктивність','Просторі загони з доступом до води','Інкубатори або природним шляхом','М\'ясо, яйця, декоративне використання','https://agromega.in.ua/imgproxy/k_yH1HtfbRMh2SAt_K1n4F5upyVNDkEFX5LQ1pQQYY8/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9jYXl1Z2EuanBn.webp','Качки породи Каюга чудо як гарні - за зовнішнім виглядом вони не поступаються декоративним породам птахів. Проте, це м\'ясо-яєчна порода качок, родом з Нью-Йоркського озера Каюга. Несучість качок Каюга становить 100-150 яєць, вага яйця - 70-80 грам. При цьому на початку яйцекладки самки несуть чорні яйця (близько десятка), з часом яйця світлішають до світло-сірого або світло-зеленого. Самки качки Каюга здатні не тільки добре насиджувати яйця, але і дбайливо водити каченят. Порода качок Каюга характеризується міцною конституцією, чорними дзьобом і лапами, середньої довжини хвостом, спрямованим вгору, темно-карими очима. Колір оперення - чорний із зеленуватим відливом, але зустрічаються і блакитні різновиди Каюги.  Качки породи Каюга найкраще набирають масу на вільному випасі, при цьому вони зовсім не шкідливі, не лізуть в городи, із задоволенням поїдаючи жучків-черв\'ячків. Чи не бояться холодів. Це слухняна, спокійна порода домашніх качок.',1),(19,'Anas platyrhynchos domesticus','Качка Кол','Птахи','Anas','Anatidae','45-50 см','1.5-2.0 кг','5-7 років','Великобританія','Всеїдні','Маленький розмір, декоративність, висока активність','Вигул на невеликих територіях, водоймища','Природним шляхом або інкубаторами','Декоративне використання, яйця','https://agromega.in.ua/imgproxy/aRTelv_IDISTw8Q1-MZoLBHbf0aKAShceXqY71in7-s/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9jYWxsX2R1Y2suanBlZw.webp','Качка Кол (Call) або \"Decoy\", як тоді було відомо, була однією з чотирьох качок у Британському стандарті 1865 року. Вона була стандартизована у кольорах Дика качка (коричнева) та Білий. Качки даної породи досить маленького розміру, тому для їх утримання достатньо невелих контейнерів з водою для купання. Через їхні розміри потрібно забезпечити безпечне місце, щоб хижаки та хижі птахи не могли їх зловити. Качки можуть добре літати за відгуками власників тому рекомендується обрізати первинні пір\'я на одному крилі щоб запобігти втечі Ваших улюбленців. Птахи дуже популярні серед дітлахів через привабливий зовнішній вигляд та дружелюбний характер.',1),(20,'Aix galericulata','Качка Мандаринка','Птахи','Aix','Anatidae','40-50 см','0.5-0.7 кг','8-10 років','Східна Азія, Європа','Всеїдні','Яскраве декоративне забарвлення, популярна серед декоративних качок','Вольєри з водоймами, захист від хижаків','Природним шляхом','Декоративне використання','https://agromega.in.ua/imgproxy/W-qppLeTT9yv5X_wPBleBy_GUScLVrUi4pviSGQZF8s/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy8xNDEzMDUyNTA3MV81YWVkMmE4M2VlX2IuanBn.webp','Качка породи Мандаринка - це різнокольоровий вид качок, який походить з Азії. Люди люблять їх гарне оперення, і через це зоопарки та приватні колекціонери тримають Мандаринок по всьому світу.Як і більшість качок, Мандаринки-самці набагато яскравіші та барвистіші, ніж самки. Самки цього виду мають переважно сіре та буре оперення, або пір’я. Самці мають гарний малюнок райдужно-червоного, коричневого, помаранчевого, зеленого тощо. Під час сезону розмноження самець також надягає «вітрило» з пір’я на спину. Цей вид качок мешкає в прибережних місцях проживання поруч з річками та потоками. Їх водні екосистеми повинні мати ліс або ліс дуже близько, оскільки вони гніздяться лише в порожнинах дерев.',1);
INSERT INTO `animals_animal` VALUES (21,'Anas platyrhynchos domesticus','Качка Мерхтемська','Птахи','Anas','Anatidae','55-60 см','3.0-3.5 кг','6-8 років','Бельгія','Всеїдні','Висока м\'ясна продуктивність, швидкий набір ваги','Вільний вигул, водоймища','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/oBb8kswwrNpTVIRJHQ94Wx-I63-n9mgTNS16Eyhffgs/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9NZXJjaHRlbUR1Y2suanBn.webp','Мерхтемська - порода походить з регіону навколо однойменного села Мерхтем. На початку ХХ століття цей регіон спеціалізувався на виробництві м\'яса птиці для Бельгійської столиці Брюсселя. Окрім мехеленської птиці, на той час найкращої м’ясної курки у світі, цей регіон був відомий також однією з найкращих м\'ясних качок того часу: качкою Мерхтем. Merchtemse - це корисна качка в найкращих випадках. Ця важка качка (3,5 кг) не тільки забезпечує багато м’яса, але і дуже ситне м’ясо гарної якості. Оперення чисто біле, без жодного жовтого нападу. Дзьоб: робить цю качку особливою, світло-рожевий, без жодного сліду жовтого пігменту. Ноги: світло-жовтого кольору. Зараз є кілька заводчиків цієї породи, які разом представляють невеликий запас у кілька десятків качок.',1),(22,'Anas platyrhynchos x Cairina moschata','Качка Мулард','Птахи','Anas x Cairina','Anatidae','60-70 см','4.0-6.0 кг','5-6 років','Світ, фермерські господарства','Всеїдні','Гібридна порода, велика вага, відсутність здатності до розмноження','Вигул, постійний доступ до корму та води','Виведення через схрещування','М\'ясо','https://agromega.in.ua/imgproxy/ToACdMsNgkpfPnQnEs91EF4B5Jj6l_R5GH1pOMn3vMA/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9tdWxhcmQxLmpwZw.webp','Муларди - це безплідні гібриди Мускусних і, найчастіше, Пекінської качки. Це птах одного сезону (купили пташенят - виростили - з\'їли), оскільки навіть якщо самка Мулардів почне нести яйця, вони 100% будуть марними. Якщо порівнювати Мулардів з батьками Індокачками, то в них відсутні такі негативні якості як повільне зростання, невелика вага, пізня статева зрілість, сильно розвинений інстинкт насиджування. У дечому виграють і чисті Індокачки - вони більш тихі, охайні, і мають куди більш ціне червоне м\'ясо. Порівняно з «Пекінкою», у Мулардів більш лагідний характер, вони тихіші, охайніші, менш ненажерливі, їх м\'ясо менш жирне, зате Пекінські більш скоростиглі, мають слабкий інстинкт насиджування, більш плідні.',1),(23,'Cairina moschata','Качка Мускусна качка','Птахи','Cairina','Anatidae','70-80 см','4.0-5.5 кг','8-10 років','Південна Америка, світ','Всеїдні','Велика вага, тихий характер, стійкість до хвороб','Просторі загони, водоймища, регулярний вигул','Природним шляхом або інкубаторами','М\'ясо, декоративне використання','https://agromega.in.ua/imgproxy/A_DgTUGKdSfXahxq7Z9vrhbAhH8-p2k4An6idnwf9QQ/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9pbmRva2FjaGthLmpwZw.webp','Мускусна качка прийшла в наші краї з Південної Америки, де ще стародавні індійці сотні років назад вирощували цих птахів. В країни колишнього Радянського Союзу мускусна качка (або Індокачка, як її у нас називають, хоча до індиків цей птах ніякого відношення не має) потрапила у 80-і роки минулого століття. Свою назву мускусна качка отримала завдяки специфічному аромату м\'яса. Качки за рік дають від 90 до 100 яєць масою близько 75 грам. Це менше, порівняно з «Пекінками», зате яйця Індокачок дуже цінні, затребувані в кулінарії, і можуть зберігатися набагато довше. Яйцекладку Мускусні качки починають у віці 6-7 місяців. Качки хороші квочки, їх нерідко використовують для насиджування курячих, гусячих, качиних яєць. Зовнішній вигляд Мускусної качки примітний: у верхній частині голови є яскраві бородавки-нарости. М\'ясо Мускусних качок - маложирне, дієтичне, дуже смачне, схоже на м\'ясо дичини, але без характерного присмаку. У Індокачок дуже високий вихід м\'язової маси (41%).',1),(24,'Anas platyrhynchos domesticus','Качка Орпінгтон','Птахи','Anas','Anatidae','55-60 см','3.0-4.0 кг','7-8 років','Великобританія','Всеїдні','Швидкий набір ваги, жовте оперення, м\'ясна порода','Просторі водоймища, регулярне годування','Природним шляхом або інкубаторами','М\'ясо','https://agromega.in.ua/imgproxy/DGzYf-oAqBX6mGS4xV-_0wzHEIssruUYaMikXIaFEgM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9PcnBpbmd0b25fRHVja18yMDE0LTEwLTIwXzAwMS5qcGc.webp','Качка Орпінгтон - порода домашніх качок, що походять з Великобританії. Вони також відомі як качка Бафф Орпінгтон. Це прекрасна порода качки подвійного призначення, яка використовується як для виробництва м\'яса, так і яєць. Качка Орпінгтон класифікується як качка середнього розміру. Це дуже красива порода качок подвійного призначення. Качки Орпінгтон мають довге, широке і глибоке тіло з поставою приблизно на 20 градусів над горизонталлю. Вони мають овальну голову, середню довжину дзьоба і довгу витончено вигнуту шию. У них невеликий, добре завитий хвіст, а крила - короткі. Качки зазвичай здатні відкладати до 220 яєць на рік. Вони відносно швидко зростають і готуються до ринку протягом 8-10 тижнів. Багато хто вважає качку Орпінгтон хорошою породою м\'ясної качки. Вони мають гарне оперення, тому що їхні легке пір\'я не видно на зірваній туші. Качка Орпінгтон - ідеальна порода для саду або заднього двору. Вони активні, менш лякливі, витривалі і зазвичай слухняні.',1),(25,'Anas platyrhynchos domesticus','Качка Ост-Індська','Птахи','Anas','Anatidae','45-50 см','1.0-1.5 кг','6-8 років','Європа, США','Всеїдні','Чорне блискуче оперення, декоративна порода','Вольєри з водоймами, регулярний догляд','Природним шляхом','Декоративне використання, яйця','https://agromega.in.ua/imgproxy/ynErLw7bKYv6N6PRhkFpreMHYHYfkaVn90OeeiyXBak/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9LYWNobmEtc21hcmFnZG92YS10YWJvci5qcGc.webp','Качка Ост-Індська (також її називають Чорно-Східна Індія або Чорно-Східно-Індійська качка) - дуже гарна порода домашніх качок, в основному вирощена в декоративних цілях або як домашні тварини. Порода найбільш відома своїми розмірами та вражаючою зовнішністю. Качки Ост-Індії мають дуже темне, блискуче зелене оперення та чорні дзьоби. У них чорні або сірі ноги і дзьоб. Качки / самки іноді можуть проявляти біле пір’я відповідно до свого віку. Східно-індійські качки, як правило, сором\'язливі і спокійні. Вони підходять для утримання з іншими неагресивними птахами. Порода не належить до числа хороших яєчних порід качок, які дають близько 40 до 100 яєць на рік. Колір яєць качки Ост-Індійської варіюється в залежності від пори року. Яйця чорного або темно-сірого кольору на початку сезону. А пізніше в сезон відкладання яйця поступово змінюються на світло-сірі або сині.',1),(26,'Anas platyrhynchos domesticus','Качка Пекінська','Птахи','Anas','Anatidae','55-65 см','3.5-4.5 кг','5-8 років','Китай, світ','Всеїдні','Висока м\'ясна продуктивність, швидке зростання','Вигул у великих загонах, доступ до води','Інкубатори або природним шляхом','М\'ясо, яйця','https://agromega.in.ua/imgproxy/P-Ot9VJFITg9dNhBySVH4RTMWsGWpKGDLtX6Yyc8_3w/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9wZWtpbnNrYS5qcGc.webp','Якщо і існує найкраща порода домашніх качок, то це - качка «Пекінка». Ця м\'ясна порода качок славиться надзвичайно активним обміном речовин. Їжа проходить через шлунок \"Пекінки\" швидко, тому качки ростуть буквально на очах, і швидко набирають вагу. М\'ясо пекінських качок ніжне, соковите, досить жирне (чим молодший птах - тим менше жиру), забійна вага - 80% від живого. Пекінські качки ненажерливі, завжди голодні, крикливі, активні, але в той же час - стійкі до зовнішніх впливів - хвороб, холодів. Качка породи Пекінська за рік дає 80-120 яєць вагою 85-90 г. Біла Пекінська качка важкий птах з характерною перевалювальною ходою.',1),(27,'Anas platyrhynchos domesticus','Качка Померанська','Птахи','Anas','Anatidae','55-60 см','3.0-3.5 кг','6-8 років','Німеччина','Всеїдні','М\'ясна порода, сильне здоров\'я, невибагливість','Вигул із доступом до водойм, захист від хижаків','Природним шляхом або інкубаторами','М\'ясо','https://agromega.in.ua/imgproxy/BVP2HY1S8rm5GwFSxG47B3geLIeRpunxayCsMMfd_8Y/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9mMzMxMjIwOWZjMTc5ZGQ5OThkYTQ2OTIyNWQ4M2JhMy5qcGc.webp','Померанська качка класифікується як птах середнього розміру. Має досить довге тіло. Але їх тіло широке і глибоке і переносить себе більш горизонтально до землі. Породу відносять до легковажної породи качок, і вони бувають двох спеціальних кольорів, таких як Чорний та Синій. Сорт Чорний з’являється разом із білим кольором і має зелений блиск над оперенням чорного кольору. А сорт Блакитний - це особливо вражаючий птах з плоским світло-синім кольором оперення та великим нальотом білого кольору на верхній частині грудей. У них темні дзьоби, бажано чорні. Ноги у них темні, а очі темно-карі. Померанська качка - качка подвійного призначення. Їх вирощують як для виробництва м\'яса, так і для яєць. Іноді їх також піднімають для підвищення краси заднього двору.  Вони відкладають близько 70-100 яєць на рік. А колір яєць білий або зеленуватий. Порода сьогодні досить рідкісна. ',1),(28,'Anas platyrhynchos domesticus','Качка Руанська','Птахи','Anas','Anatidae','60-70 см','4.0-5.0 кг','6-9 років','Франція','Всеїдні','Велика вага, м\'ясна порода, красиве оперення','Просторі водоймища, регулярне годування','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/yeoW3zF2lQNE-m04BAfIBZRMqRV3Ts_yo-PfO6MsQXk/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9yb3Vlbi1kdWNrcy5qcGc.webp','Руанські качки відносяться до важкої породи качок загального призначення. Забарвлення селезнів та качок Руана майже ідентично кольоровій Крижень (Mallard) качці та селезню. Руанські селезні мають сіре тіло, білі коміри, чорне пір\'я хвоста, зелені голови та глибоку бордову грудку. У той час як самки Руан мають строкату світло-темно-коричневу з чорною короною та смужками очей. Самки Руана можуть бути набагато темніше коричневого кольору, ніж самки Крижень. І у качок, і у селезнів також є сине відблискуюче пір’я. Але в порівнянні з Крижень пір\'я Руанської качки мають яскравіший колір і більші розміри. А повністю вирощена Руанська качка, як правило, значно важча за своїми розмірами, ніж качки Крижень. Забарвлення каченят Руана і каченят Крижень також відрізняється. Каченята Руан також можна відрізнити за наявністю другої смуги, яка проходить через їх обличчя, прямо під очима. Руанські качки слухняні, красива важка порода, що цінується за їх виробництво м\'яса. Вони не входять до числа найкращих яєчних порід качок, що виробляють близько 150 великих білих яєць на рік. Вони досить повільно дозрівають птахи і можуть зайняти рік для досягнення повного розміру.',1),(29,'Anas platyrhynchos domesticus','Качка Семоіс','Птахи','Anas','Anatidae','55-60 см','2.5-3.0 кг','6-8 років','Франція','Всеїдні','Швидкий набір ваги, висока м\'ясна продуктивність','Просторі водоймища, регулярний догляд','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/jXmg84FImM1Yu_8kwNRNxW9ZcOiLusejkLKLcUKv1Ac/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9TZW1vaXNEdWNrLmpwZw.webp','Семоіс (Semois eend) - це дивна качка серед бельгійських порід. Вона маленька, біла декоративна качка, що походить з долини Семуа. За типом качка Семо нагадує абсолютно білу обтічну дику качку з жовтим дзьобом і блідо-помаранчевими ніжками. Дзьоб досить довгий і опуклий. Також впізнається качка Semo з чубом на голові, чуб у формі кулі що знаходиться на потилиці. Качки - це жваві качки, які легко утримувати, вони висиджують яйця самі, це означає, що їх також можна використовувати як сиділки для висиджування яєць інших (декоративних) порід.',1),(30,'Anas platyrhynchos domesticus','Качка Сорока','Птахи','Anas','Anatidae','50-55 см','2.0-2.5 кг','5-7 років','Великобританія','Всеїдні','Чорно-біле оперення, декоративний вигляд, продуктивність яєць','Доступ до водойм, регулярне годування','Природним шляхом або інкубаторами','Декоративне використання, яйця','https://agromega.in.ua/imgproxy/-20QbMxNZdskK_s2nFuxS6eH1HPIvRbmlOALa1hyX3E/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy8zMjY5NDcyMzcxNF84NGZlNDdmMmRlX2IuanBn.webp','Відповідно до стандарту досконалості Американської асоціації птахівництва, качка Cорока відноситься до легкої породи домашньої качки. І названа вона за своєрідне чорно-біле оперення, що нагадує забарвлення європейської сороки. За розмірами та формою вона схожа на качку Хакі Кемпбелл, але більш міцніша. І вона помірно обтічна з дещо вертикальною поставою, що навіює качку індійського бігуна в її родовій лінії крові. Збуджена качка Сорока, як правило, стоїть вертикальніше, але розслаблена качка - горизонтальніша. Оперення качки сороки переважно біле, з двома великими чорними ділянками на спині, а також на верхівці голови. А чорна шапочка, як правило, почне вкриватися білими плямами відповідно до віку качок. Чорна шапочка з часом може стати повністю білою. Якщо з ним регулярно дивитись, качка Сорока, як правило, спокійна і послушна порода качок. Вони стають доброзичливою породою і стають легкими в управлінні, якщо регулярно доглядати їх з юного віку.Качки Сороки є одними з добрих порід качок, що відкладають яйця, і відкладають 220-290 яєць на рік. Їх яйця великі і білого кольору. М\'ясо качки сороки має вишукану якість, а тушки будуть вибирати чисто завдяки світлому забарвленню.',1),(31,'Anas platyrhynchos domesticus','Качка Срібна Епплярд','Птахи','Anas','Anatidae','60-70 см','3.5-4.0 кг','6-9 років','Великобританія','Всеїдні','Висока м\'ясна продуктивність, декоративне сріблясте оперення','Просторі водоймища, регулярне годування','Інкубатори або природним шляхом','М\'ясо, яйця, декоративне використання','https://agromega.in.ua/imgproxy/451jq0-dBrNf-YXZ67TmLfFALw-ptM88keKYq9Jv6fE/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9TaWx2ZXJfQXBwbGV5YXJkcy5qcGc.webp','Качка породи Срібна Епплярд відноситься до важкої породи качок. Це дуже красива качка подвійного призначення, яка підходить як для виробництва м\'яса, так і яєць. На вигляд це велика і міцно побудована порода качок. Дзьоб селезнів зеленуватого або жовтого кольору з чорним наконечником. Очі у них карі, а голова і шия - зеленувато-чорні (іноді виявляються смугастими з віком). Груди, плечі та боки на селезні червонувато-каштанові з білою глазур\'ю та шнурівкою. Ноги в них і стопи помаранчеві, а хвіст - чорнувато-бронзовий. Нижня частина тулуба у селезня кремово-сріблясто-білого кольору, а крила сірі та білі з яскраво-синьою перехресною смужкою. З іншого боку, у самок є жовтий або оранжевий дзьоб з чорною горошиною, а очі карі. Їх ноги і стопи помаранчевого кольору з темними нігтями на ногах. Качки Срібна Епплярд підходять для всіх цілей. Їх вирощують для прикраси, виставки, як домашніх тварин, яєць та смажених качок для гурманів. Качки, як правило, відкладають близько 250 яєць на рік.',1),(32,'Anas platyrhynchos domesticus','Качка Сіра Українська','Птахи','Anas','Anatidae','55-60 см','3.0-3.5 кг','6-8 років','Україна','Всеїдні','Витривалість, висока продуктивність м\'яса та яєць','Просторі водоймища, вигул на свіжому повітрі','Інкубатори або природним шляхом','М\'ясо, яйця','https://agromega.in.ua/imgproxy/wewmCcdcJjuyZ_AUHsGozqnGwBi1TdKNVYDX_h31eeM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9zaXJhX3VrcjEuanBn.webp','Качки породи Сіра українська за рік зносять близько 120 яєць вагою 70-90 грам, хоча при належному догляді можуть дати більше 200 яєць за яйцекладку. Сіра українська качка може харчуватися і травою, і самостійно добутою на водоймі ряскою, і комбікормами, та зерном. Качки породи Українська сіра характеризуються тонким кістяком, добре розвиненою мускулатурою, міцною конституцією, рясним і одночасно легким оперенням, короткими міцними ногами, глибоким, довгим і широким корпусом. Сіра українська качка характеризується забарвленням оперення, як у диких качок крижнів, причому у самок і самців воно відрізняється. Існують і інші різновиди українських качок - глинисті та білі.',1),(33,'Anas platyrhynchos domesticus','Качка Шведська Синя','Птахи','Anas','Anatidae','55-65 см','3.0-3.5 кг','7-8 років','Швеція','Всеїдні','Синє-сіре оперення, хороша м\'ясна продуктивність','Вигул у вільних загонах, водоймища','Інкубатори або природним шляхом','М\'ясо, яйця','https://agromega.in.ua/imgproxy/sV3PPjkqK1WlRbjtLhyFo8I4d5olAvKgfnWATNSsmQE/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9ibHVlLXN3ZWRpc2gtZHVja2xpbmdzLmpwZw.webp','Шведська Блакитна качка - птах середньої величини. За розмірами він схожий на Руанських качок. Це прекрасний птах і має вражаючу зовнішність з чудовими чорними головами, білими нагрудниками та чудовим світло-блакитним тілом. Їх тіло схоже на качку Пекін. Їх білі кольорові нагрудники простягаються з-під дзьобу до напівгрудей. Голова середньої довжини. Також на крилах Шведської Блакитної качки є білий колір, який створює дуже привабливий для очей контраст із синім. Оперення як качок, так і селезнів є рівномірним синюватим шифером. А ніжки Шведської Блакитної качки мають характерний коричневий колір, що надає їм прямого вигляду. Вони підходять як для виробництва м\'яса, так і для яєць. Качки будуть відкладати близько 100-150 яєць на рік. Яєчний колір Шведської Блакитної качки - білий, зелений або синій відтінок. Порода є дуже хорошим кормошукачем і хорошим для розведення качок на вільному вигулі. ',1),(34,'Anas platyrhynchos domesticus','Качка Шетландська','Птахи','Anas','Anatidae','50-55 см','2.0-2.5 кг','6-8 років','Шетландські острови, Великобританія','Всеїдні','Міцна будова, стійкість до холоду, висока несучість','Вигул на відкритому повітрі, водоймища','Природним шляхом або інкубаторами','Яйця, м\'ясо','https://agromega.in.ua/imgproxy/4zl8qudv7MVk49vvQtwWjRGwv5TwJopLD9JKus8EKps/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9zaGV0bGFuZC1kdWNrLWQxOTNhZjA1LWZkYzQtNDYwNi04YjU0LTIzMzFmYjg3YmMyLXJlc2l6ZS03NTAuanBlZw.webp','Шетландська качка класифікується як невелика порода качок. Порода чорна з білим нальотом і, як правило, має блакитні дзьоби. Як селезні, так і качки мають зрілий темно-чорний колір з білим нальотом. Хоча нагрудник, як правило, нерегулярний. Основна відмінність Шетландської качки від селезня - їх дзьоби. У качок майже чорний дзьоб, у селезнів темно-зелені дзьоби. Качки мають помаранчеве забарвлення на ногах, але ноги качок чорні.\nШетландські качки - досить жорстка і холодостійка порода. Вони зайняті качки, завжди активні та дуже хороші кормозбирачі. Вони дуже доброзичливі зі спокійним темпераментом. Вони люб’язні і продуктивні маленькі птахи для будь-кого, вони навіть хороші породи для початківців. Качки, як правило, відкладають до 150 яєць на рік і мають тенденцію до висиджування. Їх колір яєць - білий. ',1),(35,'Anas platyrhynchos domesticus','Качка Хакі Кемпбелл','Птахи','Anas','Anatidae','50-60 см','2.0-2.5 кг','6-8 років','Великобританія','Всеїдні','Висока несучість (до 300 яєць на рік), легке тіло','Просторі загони, регулярний вигул та доступ до води','Інкубатори або природним шляхом','Яйця, м\'ясо','https://agromega.in.ua/imgproxy/sPcXlDknoytiwbqHTabegnGaXaMKZ7sRaw3797Iz2O4/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9oYWtpX2tlbXBiZWxsLmpwZw.webp','Качки породи Хакі Кемпбелл за яйцекладку, що настає у віці півроку, дають 250-350 яєць вагою 65-85 грам. Квочки з Хакі Кемпбелл виходять неважні. Порода качок Хакі Кемпбелл характеризується обтічним корпусом, невеликою головою, темно-помаранчевими ногами, легким кістяком. Забарвлення може бути як класичним Хакі, так і білим, строкатим і темним. Ця порода домашніх качок любить відкритий простір - пасовища, водойми. Незважаючи на миролюбний, слухняний характер, качки Хакі Кемпбелл дуже енергійні, легко збудливі, мають потребу у великому відкритому просторі. Тільки в такому випадку вони зможуть розкрити свій потенціал.',1),(36,'Anas platyrhynchos domesticus','Качка Чорна білогруда','Птахи','Anas','Anatidae','55-60 см','3.0-3.5 кг','6-8 років','Східна Європа','Всеїдні','Чорне оперення з білою грудкою, м\'ясна продуктивність','Просторі водоймища, регулярне годування','Природним шляхом або інкубаторами','М\'ясо','https://agromega.in.ua/imgproxy/e63znH7jQzHfYbjK-xeaudNC83oSaIMURe33Bx1qEQ4/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9ibGFja193aGl0ZV9kdWNrLmpwZw.webp','Качка породи Чорна білогруда за період яйцекладки дає 120-130 яєць вагою до 90 грам, при цьому виводимість пташенят становить 65%, збереження молодняку ​​- 90-92%, дорослої птиці - 95-96%. Качки Чорні білогруді характеризуються помітно піднятим тулубом з нахилом до хвоста, глибокими грудьми, довгою широкою спиною, піднесеним хвостом, чорними короткими міцними ногами, увігнутим темним дзьобом, міцними крилами. Забарвлення пір\'я - чорне, з білим животом і грудкою. Селезнів породи Чорні білогруді можна дізнатися по синьо-фіолетового відливу на верхній частині шиї.',1),(37,'Anas platyrhynchos domesticus','Качка Чубата','Птахи','Anas','Anatidae','50-60 см','2.0-2.5 кг','6-8 років','Європа','Всеїдні','Чубчик на голові, декоративна порода','Вигул у невеликих загонах, водоймища','Природним шляхом або інкубаторами','Декоративне використання, яйця','https://agromega.in.ua/imgproxy/r0L5jEauzTXyivNBdKghIbfkQd0zL9g-Q3xqob3erg8/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9jaG9obGF0YXlhLmpwZw.webp','Чубата порода має невеликі розміри, проте статура мускулиста і щільна. Спина досить довга і широка. Груди мають заокруглену форму, трохи опуклі. Голова невеликих розмірів, на потилиці є твердий пір\'яний чубчик. Дзьоб середньої довжини, колір його залежить від кольору оперення, чим світліше оперення, тим світліше дзьоб. Шия середньої довжини, трохи загинається вперед. Крила добре розвинені, розмашисті, щільно прилягають до тулуба. Оперення щільне, жорстке. Несучість у чубатих, невисока, всього - 50-60 яєць на рік, деякі рекордистки серед чубатих качок зносять і 120 яєць. Маса яйця становить - 60-80 гр. Чубата качка, це дуже рухливий птах з красиво вигнутою шиєю. Характер у качок, спокійний, миролюбний. Чубчик на голові завжди трохи світліше основного оперення, і зустрічається не у всіх представників породи: якщо один з батьків його не має, в подальшому нащадки втрачають цю особливість.',1),(38,'Anser anser domesticus','Гуска Австрійський Ландрас','Птахи','Anser','Anatidae','70-90 см','6.0-8.0 кг','7-10 років','Австрія','Всеїдні','Швидкий набір ваги, витривалість до холодів','Просторі загони, доступ до води, регулярне годування','Природним шляхом або інкубаторами','М\'ясо, пух, яйця','https://agromega.in.ua/imgproxy/9DBtoappT-iSWtci12gAJg9ekEgeWYBLbHmh5b4wzKc/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9hdXN0cmlhX2xhbmRnYW5zX2dvb3NlLmpwZw.webp','Австрійські Ландраси - це м\'яка порода гусей, яка належить по екотипу до Альпійських Ландрасів. Місце виведення гусей даної породи в основному ніщо більше, ніж ті гуси, які раніше були знайдені в кожному сільському ставку в більш ранні часи. Протягом багатьох століть вони були широко поширені і цінувалися перш за все за свою комерційність. Надійні гуси які шукали більшу частину своєї їжі самі, і завдяки своїм добре розвиненим розплодом розмножувалися без будь-яких проблем і без втручання людини. Птахи є придатними для польоту, але дуже локально. Проте, вони рідко рухаються далі, ніж на 50 м від водойми. Самки відкладають - 12-15 яєць / рік.',2),(39,'Anser anser domesticus','Гуска Американська Жовта','Птахи','Anser','Anatidae','65-80 см','5.5-7.0 кг','7-10 років','США','Всеїдні','Жовтувате оперення, висока продуктивність яєць','Вигул на свіжому повітрі, регулярний доступ до води','Природним шляхом або інкубаторами','Яйця, М\'ясо','https://agromega.in.ua/imgproxy/NglnU0y-ncus2jq9XD0tzBW7VfDsjaCBkM2fImlTeao/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9hbWVyaWNhbl9idWZmX2dvb3NlLmpwZw.webp','Американська Жовта - порода гусей середнього розміру з прекрасним абрикосово-палевим кольором. Пофарбовані пір\'я на спині та по боках облямовані кремово-білим кольором. Живіт цих птахів майже білий. Їхні ноги та дзьоб мають помаранчевий до червонувато-оранжевого кольору. І жорсткий ніготь на кінчику - блідо-рожевого кольору. Очі коричневого кольору. Під час відкладання яєць ноги можуть міняти колір до рожевого, або коли зеленої трави немає. Шия середньої довжини з глибоко борозним пір\'ям. Вони мають тіло з невеликим або зовсім відсутнім кілем, злегка вигнутою спинкою і двома округлими жирними лопатями на животі. Американська гусак добре відома своїм відносно спокійним характером, у породи слухняний темперамент. Ці птахи є добрими батьками і добре піклуються про своїх гусенят. Їх гарна поведінка робить їх ідеальними для загальних цілей. Порода дуже гарна як для виробництва м\'яса, так і для виробництва яєць. Гуси в середньому складають від 15 до 25 яєць на рік.',2),(40,'Anser cygnoides domesticus','Гуска Африканська','Птахи','Anser','Anatidae','80-90 см','7.0-9.0 кг','8-12 років','Африка, світ','Всеїдні','Велика вага, декоративний наріст на голові, м\'ясна порода','Просторі водоймища, регулярне годування, захист від хижаків','Природним шляхом або інкубаторами','М\'ясо, декоративне використання','https://agromega.in.ua/imgproxy/IOltiXryin4Nf0hiMBNrLJtIuxZof92dcMjsDixBRK0/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9hZnJpY2FuX2dlZXNlLmpwZw.webp','Африканська гуска - важка порода. Але це не така, як Тулуза або Білий Ембден. Проте Африканська гуска росте і дозріває раніше за ці дві порід. Вони відрізняються від інших гусячих і мають великий чорний ріг на голові і темну смужку вниз по задній частині шиї. Порода дуже гідно виглядає і привертає велику увагу. Гусаки повільно розвиваються, від 12 до 36 місяців. Африканські гуси з\'являються в трьох кольорах, які є Buff, Коричневий та Білий. Білий сорт має всі білі оперення та оранжеві дзьоб та ноги. А сорт Браун має оперення з нерівними відтінками, від дуже світлого до темно-коричневого. І вони мають чорні дзьоб і ноги. Самки не входять до числа несучок. Зазвичай вони кладуть 20-40 яєць на рік. Їх яйця дуже великі і білого кольору. Їх яйця вагою 5-8 унцій і вилуплюються через 30-32 дні.',2);
INSERT INTO `animals_animal` VALUES (41,'Anser anser domesticus','Гуска Баварський Ландрас','Птахи','Anser','Anatidae','Великий','5-6 кг','10-15 років','Німеччина','Травоїдні','Висока м’ясна продуктивність, хороша адаптація до клімату','Вигул на пасовищі, доступ до водойм','Природним шляхом або інкубаторами','М’ясо, жир','https://agromega.in.ua/imgproxy/FynLh7yZeYTBNCZu3Iwh_touaTi7MSa124USaAgj-9o/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9iYXllcnNoaW5lX2xhbmRyYWNlX2dvb3NlLmpwZw.webp','Баварський Ландрас — велика м’ясна порода гусей, виведена у Німеччині, має міцну статуру і спокійний характер. Шия середньої довжини, елегантна статура, гнучка, горда і вертикальна постава, жива істота. Розводяться надійно і самостійно. М\'ясо дуже гарної, дрібнозернистої і нежирної якості, невибаглива до пасовища гуска, здатна літати, але правильно розташуватися. Навесні відкладають між 10-13 яєць. Друге зчеплення може бути створене у випадку втрати потомства і містити 6-9 яєць. На пасовищі породу можна утримувати з низькими витратами з достатньою кількістю зелених насаджень. Негативні риси: вузька грудна клітка, горло-черви, фізичні каліки, висячі і розмахуючі крила, хвіст як віяло.',2),(42,'Anser anser domesticus','Гуска Бреконський Буйвол','Птахи','Anser','Anatidae','Великий','6-7 кг','12-15 років','Великобританія','Травоїдні','Висока вага, стійкість до хвороб','Вільний вигул на пасовищах із водоймами','Природне та інкубаторне розмноження','М’ясо, пір’я','https://agromega.in.ua/imgproxy/K--6meVIxzcbOxfajo-HdS-iCovrlSf79QINiA6EPHI/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9CcmVjb25fQnVmZl9Hb29zZS5qcGVn.webp','Гусак Брекон Бафф - порода середнього розміру з буйоволиним оперенням. Його легко відрізнити від його більшого родича, Американського Буйволиного гусака, не тільки за його вагою, але також за його рожевим дзьобом і лапками. Під підборіддям, в первинних або вторинних пір’ях не повинно бути білих пір’їн. Гусак породи Бреконський Буйвол - дуже витривала, пильна і активна порода гусей. За рік гуси несуть близько 10-25 яєць. Вони виходять хорошими виводками і дуже добре доглядають за своїми дитинчатами. Ці птахи стають дуже ручними, якщо з ними добре поводитися, а також дуже хороші як домашні тварини. Вони досить повільно ростуть, але відмінно пасуться і дуже добре працюють у системі вільного вигулу.',2),(43,'Anser anser domesticus','Гуска Італійська','Птахи','Anser','Anatidae','Середній','4-5 кг','10-12 років','Італія','Травоїдні','Висока несучість, швидкий ріст','Вигул у загонах із доступом до води','Природне або інкубаторне','Яйця, м’ясо','https://agromega.in.ua/imgproxy/xmO3SLyEvhR87Cq9Icemi_0Ns62oN6kj__ll_jK8Ivo/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9pdGFsaWFfaHVzeS5qcGc.webp','Гуси породи Італійська біла виділяються своїм білосніжним забарвленням, коротким міцним дзьобом, невелика товста шия, відносно невеликим, акуратним тулубом. Гуси Італійської породи мають гарні відтворювальні якості - самки за період яйцекладки дають 40-50 яєць масою 160-170 г і з виводимістю молодняка 70%. Статевозрілою вважається птах, що досяг 240 днів. Італійські гуси можуть міститися без водойми (це не заважає їм паруватися). Відрізняються самостійним характером, і ніколи не змішуються в стадах з гусьми інших порід.',2),(44,'Anser anser domesticus','Гуска Велика сіра','Птахи','Anser','Anatidae','Великий','6-8 кг','10-15 років','Європа','Травоїдні','Потужна статура, стійкість до холодів','Вигул на природі, доступ до води','Природне та штучне розведення','М’ясо, пух','https://agromega.in.ua/imgproxy/-B33NYCaD8KahhFJtFUHMXQ57P55yYGCYp9s9dP9EsE/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy92ZWx5a2lfc2lyaS5qcGc.webp','Ці гуси мають невелику голову, іноді - з чубчиком, товсту середньої довжини шию, широкий тулуб з глибокими грудьми, двома жировими складками ні животі і потужними крилами. Оперення - завжди сіре, різних відтінків на різних ділянках: живіт білий, груди - світло-сірі, верхня частина спини, шиї і голова - темно-сірі, а на спині обов\'язково присутній лускатий малюнок - вірна ознака породи гусей Великі сірі. Самка Великих сірих гусей за період яйцекладки встигає знести близько 40 яєць середньою масою 175 грам. Виживання гусенят - в районі 60%. Гуски досить добре насиджують і вирощують потомство. Відмінні риси Великих сірих гусей - вони рухливі, люблять довго гуляти, витривалі, причому можуть обходитися без водойм.',2),(45,'Anser anser domesticus','Гуска Ельзаська','Птахи','Anser','Anatidae','Великий','6-7 кг','10-15 років','Франція','Травоїдні','Висока м’ясна продуктивність, гарне світле оперення','Вільний вигул з доступом до водойм','Природне або інкубаторне','М’ясо, жир, пух','https://agromega.in.ua/imgproxy/ZAHfD3GOQ2e29TTYnQ8HszGpCSbGYY4eP3ROmKCOzlI/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9PaWVfZEFsc2FjZV9waWUuanBlZw.webp','Ця гуска була розроблена для вирощування великої жирної печінки фуа-гра виробництво. Відібрані для цієї мети гуси мають коротші ноги і ширше тіло. Ця форма тіла дозволяє розвивати внутрішні органи, особливо печінку. Гусей, печінка яких не вважається придатними для використання фуа-гра, забивають на м’ясо. Гуси, відібрані для цієї мети, мають шпунти і ширші тіла. Ця форма тіла дозволяє розвивати внутрішні, зокрема лівер. Гуси, чиї леви не зважають придатними для використання для фуа-Грас, засікаються для їх м\'яса.',2),(46,'Branta canadensis','Гуска Канадська Казарка','Птахи','Branta','Anatidae','Великий','3-6 кг','10-24 роки','Північна Америка','Травоїдні','Довга шия, чорна голова з білою «маскою»','Природний ареал з водоймами, часто в дикій природі','Природне розмноження','Спостереження, озеленення водойм','https://agromega.in.ua/imgproxy/MJqZBv45ab3uWji-8HlxvDBb6XBKB0rcYHNuVLwwbwA/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9rYW5hZHNrYV9rYXphcmthLmpwZw.webp','Чорні тільки голова і шия, на задніх частинах щік і в вушній області є великі білі плями, які не заходять вперед за лінію, що йде від зони під дзьобом до ока. Черево, боки, спина і пір\'я, що криють крила сірувато-бурі, зі світлими білими облямівками на пір\'ї, що утворюють довгі поперечні лінії на корпусі. На грудях велике світліших тонів оперення до світло-бежевого. Махові пера темно-бурі, кермові - чорні з білою облямівкою, подхвістя біле. Самці більші за самок, з більшим дзьобом. Дзьоб і лапи чорні. У молодих птахів світлі облямівки на пір\'ї корпусу мають охристий відтінок і утворюють великий лускатий малюнок. Дзьоб і лапи світліше, ніж у дорослих птахів, що не чорного, а брудно-бурого кольору.',2),(47,'Anser cygnoides','Гуска Китайська','Птахи','Anser','Anatidae','Середній','4-5 кг','12-15 років','Китай','Травоїдні','Висока несучість, витягнутий дзьоб, декоративний вигляд','Вільний вигул у загонах із водою','Природне та інкубаторне розведення','Яйця, декоративне утримання','https://agromega.in.ua/imgproxy/qiPd8XqPxIp0SGQsXTkf0L6fe-Pqm_IVb8whssMEhgY/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9jaGluZWVzZV9nZWVzZS5qcGc.webp','Це дуже стара легка порода гусей, яка на сьогоднішній день в чистому вигляді майже не розводиться, але цінується при схрещуванні з важкими породами гусей за свою плодючість, скороспілість, високі кількісні та якісні показники несучості. Навіть зовні гуси породи Китайська помітно відрізняються від своїх європейських родичів ніжнішою, лебединою шиєю. Відтворювальні якості гусей породи Китайська дуже високі - 50-70, а іноді - до 100 яєць за період яйцекладки. Вага яйця - близько 120 г, виводимість гусенят з яєць - 75-80%, збереження молодняку ​​- 99%. Гуси Китайської породи відрізняються довгою шиєю, великою шишкою на лобі, яка може посилюватися невеликий гаманець під дзьобом, тулуб яйцевидної форми, трохи піднесений, груди - широкі. У Білих Китайських гусей оперення чисто біле, лапи, дзьоб і шишка помаранчеві; у Сірих Китайських гусей окрас сіро-бурий, верх грудей і передня частина шиї брудно-білі, груди блідо-коричнева, нижня частина і живіт - білі, а від верху голови до плечей проходить темно-коричневий «ремінь», шишка і дзьоб - чорні.',2),(48,'Chloephaga picta','Гуска Магеланова','Птахи','Chloephaga','Anatidae','Середній','3-4 кг','8-12 років','Південна Америка','Травоїдні','Характерне біле або коричневе оперення, пристосованість до дикої природи','Природне середовище існування','Природне розмноження','Декоративне спостереження','https://agromega.in.ua/imgproxy/_hqHdUz35CUUvVIleedqlVOEhSryt0akcmzpu53J92c/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9tYWdlbGFuX2dvb3NlLmpwZw.webp','Гуси живляться переважно рослинним матеріалом. Під час годування у воді вони занурюють свої голови і шиї, щоб дістатися до водних рослин, іноді перекидаючись вперед, як утираюча качка. Зграї цих птахів часто харчуються залишеними культивованими зернами на полях, особливо під час міграції або взимку. Качки та гуси, як правило, харчуються личинками і лялечками, які зазвичай знаходяться під скелями, водними тваринами, рослинним матеріалом, насінням, дрібною рибою, равликами і крабами. Самців можна ідентифікувати за своїми білими головами і грудями. Самки мають переважно коричневе оперення з чорно-смугастими крилами і жовтими ногами. Самки нагадують рум\'яних гусей.',2),(49,'Anser anser domesticus','Гуска Легарт','Птахи','Anser','Anatidae','Великий','6-7 кг','10-12 років','Данія','Травоїдні','Висока несучість до 50-60 яєць на рік, швидкий ріст','Вигул на пасовищі з водоймами','Природне або інкубаторне','Яйця, м’ясо','https://agromega.in.ua/imgproxy/6xjvcpv75-P4q3919ealHYdVhQnpvODucnJ2Yh3kuYc/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9sZWdhcnQuanBn.webp','Гуски породи Легарт неважливі квочки, за яйцекладку дають 30-40 яєць вагою 190-200 г. У яєць не дуже висока виводимість - до 65%, зате гусенята відрізняються високим виживанням і дуже швидким набором ваги, що повністю компенсує їх порівняно невелику масу тіла. Гуси породи Датський Легарт приземкуваті, великовагові, з дрібною ходою, глибоким подовженим тулубом, середньою шиєю і невеликою жировою складкою на животі. Відмітна риса гусей Легарт - блакитні очі і яскраво-біле оперення (чорні плями є тільки у маленьких гусенят). Порода гусей Данський Легарт невибаглива до умов утримання, добре нагулює вагу на пасовищі.',2),(50,'Anser anser domesticus','Гуска Ландська','Птахи','Anser','Anatidae','Великий','7-8 кг','10-12 років','Франція','Травоїдні','Висока жирова продуктивність, використання для фуа-гра','Вигул у загонах з годуванням на відгодівлю','Природне або примусове','М’ясо, фуа-гра, жир','https://agromega.in.ua/imgproxy/67V1RANv5Lsy2DXP-1dUnTvtPWN5QMV2N4Bete3TArM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9sYW5kc2tpLmpwZw.webp','Самки гусей Ландської породи непогані квочки, за яйцекладку дають до 30 яєць, виводимість гусенят низька - 45-50%, збереження молодняку ​​- 85%. Ландська порода гусей характеризується короткою широкою шиєю, жировими мішками на животі, красивим лускатим малюнком оперення на крилах, масивним тулубом, широкою головою, глибокими широкими грудьми. Гуси відрізняються сміливістю і ретельно охороняють своє стадо.',2),(51,'Anser anser domesticus','Угорські гуси','Птахи','Anser','Anatidae','Середній','4-6 кг','10-12 років','Угорщина','Травоїдні','Швидкий набір ваги, стійкість до хвороб','Вигул на пасовищі з водоймами','Природне або інкубаторне','М’ясо, пух','https://agromega.in.ua/imgproxy/bAXPsP4X_QuJfHnGuN7fc61bL7GBXWd8U2qthxnndpM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy91Z29yc2tpZV9odXN5LmpwZw.webp','Гуски породи Угорська дають 35-40 яєць за яйцекладку, виводимість гусенят - 65-70%, збереження дорослого стада - 97%. Гуси Угорської породи мають біле оперення, коротку шию, компактний широкий тулуб, широкі та глибокі груди, масивні короткі ноги, помаранчевий дзьоб і лапи. Порода гусей Угорська цінується своїм перопуховою сировиною - з однієї голови можна отримати до 110 г сировини з високим вмістом пуху. Угорські гуси дуже добре набирають масу на пасовищному кормі.',2),(52,'Anser anser domesticus','Гуска Фламандська','Птахи','Anser','Anatidae','Великий','6-7 кг','10-12 років','Бельгія','Травоїдні','Висока м’ясна продуктивність, швидкий набір ваги','Вигул на пасовищі з водоймою','Природне або інкубаторне','М’ясо, пух','https://agromega.in.ua/imgproxy/_-V7EihOyYoqbiXhxszTu5zwMl0AyQYJF737gw77L7Q/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9WbGFhbXNlX2dvb3NlLmpwZw.webp','Фламандська порода гусей — велика бельгійська порода з добрими м’ясними характеристиками та швидким ростом. У цих птахів все оперення біле, крім голови та верхньої частини шиї, плечей, хвоста та стегон, які сірі. Гусей «скубали» до чотирьох разів на рік. Таким чином були отримані білі ручки для письма та білі пухові пір’я, а птахи із сірими пір’ям мав достатній захист від погодних умов. Форма і статура Фламандського гусака показують, що ми маємо справу з справжнім гусаком. Відносно коротка, товста шия характерна для цієї гуски. Дзьоб оранжево-жовтий, а ноги - на пурпурово-рожеві на біло-оранжево-жовтому.',2),(53,'Meleagris gallopavo','Бельтсвільська мала біла індичка','Птахи','Meleagris','Phasianidae','85-95 см','6-10 кг','5-7 років','США','Всеїдні','Компактний розмір, висока продуктивність м\'яса','Просторі загони, регулярне годування','Природним шляхом або інкубаторами','М\'ясо','https://agromega.in.ua/imgproxy/USzGflb05RRUp1j_EnoMKSV-GlwWelEMbR0P52sEUqo/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9iZWx0c3ZpbGxfc21hbGxfdHVya2V5LmpwZw.webp','Бельтсвільська мала біла — компактна порода індичок, виведена для високої продуктивності м\'яса. Порода вступила в експлуатацію в 1940-х роках і була визнана Американською асоціацією птахівників у 1951 році. Набула популярності в середині 1950-х років і, крім використання в якості чистокровної, Бельсвільська індичка також сприяла розвитку інших штамів середніх та малих білих індиків, хоча ці популяції ніколи не були дуже добре визначені як породи.  Бельтсвільська індичка володіла гарними репродуктивними якостями, включаючи здатність до природного зближення, і тому їх можна вибирати, вирощувати і підтримувати дрібними виробниками. На відміну від Широкогрудих білих індичок, як правило, потрібно штучне осіменіння для розмноження.',3),(54,'Meleagris gallopavo','Блакитна індичка','Птахи','Meleagris','Phasianidae','90-110 см','7-12 кг','5-8 років','Європа','Всеїдні','Блакитне оперення, стійкість до захворювань','Вільний вигул, доступ до корму та води','Інкубатори або природним шляхом','М\'ясо, декоративне використання','https://agromega.in.ua/imgproxy/vNmLAjYzJZgupMZG6FZDFTn7ZuaVC_VA_Bb_IDlQSxM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9UaGVTbGF0ZVR1cmtleS5qcGc.webp','Блакитна сланцева індичка, також відома як сланцева індичка або лавандова індичка, — це порода домашніх індиків зі Сполучених Штатів, відома своїм виразним шиферно-сірим оперенням. Точне походження цієї породи невідоме, але припускають, що це схрещування між чорною індичкою Норфолк та східною дикою індичкою або між чорною індичкою та білою індичкою, хоча цій теорії бракує істотних генетичних доказів. Що стосується фізичних характеристик, сланцеві індики — птахи середнього та великого розміру з гарним зовнішнім виглядом. Вони можуть мати різні відтінки від чисто чорного до білого, але лише попелясто-сірі птахи мають право виставлятися за стандартом досконалості Американської асоціації птахівників. Ці птахи в першу чергу відомі своїм забарвленням, яке зазвичай від однотонного до попелясто-блакитного по всьому тілу, іноді з кількома чорними плямами. Голова, горбки та горло сланцевої індички від червоного до синювато-білого, з дзьобами рогового кольору, карими очима, чорною бородою та зазвичай рожевими гомілками та пальцями. Сланцевих індиків в основному вирощують для виробництва м’яса. Вони відомі як витривалі птахи з переважно слухняним темпераментом, хоча деякі можуть стати агресивними. ',3),(55,'Meleagris gallopavo','Бронзова індичка','Птахи','Meleagris','Phasianidae','100-120 см','8-15 кг','6-8 років','США, Європа','Всеїдні','Темне блискуче оперення, м\'ясна продуктивність','Просторі пасовища, регулярне годування','Природним шляхом або інкубаторами','М\'ясо','https://agromega.in.ua/imgproxy/TLmJNLHV79J0LpfCa0YWae5V9V5mWnDMuho8KO4j58o/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9icm9uemVfdHVya2V5LmpwZw.webp','Бронзова індичка - це середні та великі птахи з величним та вражаючим виглядом. Вони дуже красиві птахи і добре відомі своїм унікальним оперенням. Ці птахи були відібрані за великим розміром, а значно більші птахи стали називати Broad Breshed Bronze, а досить маленькими птахами стали стандартні Бронзові індички. Окрім різниці в розмірах, оперення Стандартної бронзи, як правило, світліше і блискуче, аніж бронзовий брусок. Обидва різновиди мають коричневий колір, який виділений відтінками міді та синьо-зеленого кольору, а загальна кількість оперення дуже подібна до дикої індички.',3),(56,'Meleagris gallopavo','Бурбонська Червона індичка','Птахи','Meleagris','Phasianidae','90-110 см','7-12 кг','5-8 років','США','Всеїдні','Червоне оперення, висока якість м\'яса','Вигул на свіжому повітрі, регулярне годування','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/1ToaCed45VmSGt7i8V5D-JPyayQctDRRxOm7tGn4AD0/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9idXJib25fcmVkX3R1cmtleS5qcGc.webp','Бурбонські Червоні індики - це великі птахи з дуже гарною зовнішністю. Їх пір\'я мають темний основний колір з білими первинними пір\'ями у хвості, який характеризується м\'якою червоною смугою та білими пір\'ями. Як крила, так і хвіст мають каштанові покриви. У них білі махові пір\'я крил і хвоста та коричнево-темно-червоне оперення решти тіла. Пір\'я на грудях і шиї - з каштаново-червоного дерева, а пір\'я на піднебінні - легкі, майже білі. Дзьоб у Бурбонської індички - легкого рогового кольору на кінчику і темний біля основи. Стравохід - червоного кольору, який змінюється до синювато-білого кольору. Борода чорна, а пасма і пальці рожевого кольору.',3),(57,'Meleagris gallopavo','Індичка Буф','Птахи','Meleagris','Phasianidae','85-100 см','6-10 кг','5-7 років','США','Всеїдні','Світло-коричневе оперення, невеликий розмір','Просторі загони, доступ до води','Природним шляхом або інкубаторами','М\'ясо','https://agromega.in.ua/imgproxy/qYiIAqXnPBAjald0FdF9kdOZ8LkvEk24a-cSl3vOJUQ/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9idWZmVHVya2V5LmpwZWc.webp','Буф — компактна порода індичок зі світло-коричневим забарвленням та хорошою м\'ясною продуктивністю. Buff індики мають великий розмір і округлу форму тіла. Їх забарвлення пір\'я - світло-бежеве або пісочного відтінку, що надає їм теплий та привабливий вигляд. У них також є довгий шишкоподібний дзьоб жовтого кольору та червоні гачки на голові. Buff індики відрізняються своєю спокійною та дружелюбною натурою. Вони є відмінними легкими м\'ясними породами та також добре нестимуться. Buff індики використовуються як м\'ясна порода, оскільки вони мають великі розміри та смачне м\'ясо. Вони також добре нестимуться і можуть забезпечити господарство яйцями. ',3),(58,'Meleagris gallopavo','Біла Голандська індичка','Птахи','Meleagris','Phasianidae','85-100 см','6-9 кг','6-8 років','Нідерланди, США','Всеїдні','Біле оперення, висока несучість','Просторі загони з вигулом, регулярне годування','Природним шляхом або інкубаторами','М\'ясо, яйця','https://agromega.in.ua/imgproxy/LS8Amd7NXsVEw0OAku0VrZdGRjk9Q-_7p8Sjs_8i1Mo/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9XaGl0ZUhvbGxhbmQuanBn.webp',' Біла Голландія Індички - це старий сорт вітчизняної турки. Біла Голландія виникла з хрестів білого європейського турецького дерева, що вивозиться в Північну Америку і перетинається з місцевими птахами. Біла Голландія вперше була визнана Американською асоціацією птахів у 1874 році, і сьогодні вона вважається спадщиною індички. В даний час вони перераховані в якості загрози ThernLivestock Conservancy.',3),(59,'Meleagris gallopavo','Біла Широкогруда індичка','Птахи','Meleagris','Phasianidae','90-120 см','8-15 кг','5-8 років','США','Всеїдні','Широка груди, велика м\'ясна продуктивність','Просторі пасовища, регулярний вигул','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/mUh3rVAOZ5s3wyyaqtOnHJCT2tVYk1_vbQTFFW1Pk3M/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy93aGl0ZV93aWRlYnJlc3RfdHVya2V5LmpwZw.webp','Біла Широкогруда індичка — найбільш популярна м\'ясна порода завдяки великій вазі та швидкому росту. Білий Широкогрудий індик - порода індиків виведені в США в 60 - х роках ХХ століття. Дана порода була отримана шляхом схрещування Білої Голландської з Бронзовою Широкогрудою. Індики даноі породи були завезені на територію тодішньої СРСР в 1970 році з Англії після чого поширились по території України. Птахи відрізняються найкращими м\'ясними якостями, гарним товарним виглядом тушки, (жовтуватим відтінком шкіри), хорошою м\'ясною скоростиглістю, більш високою, в порівнянні з Бронзовими Індичками, яйцекладкою (80-90 яєць).',3),(60,'Meleagris gallopavo','Жерська індичка','Птахи','Meleagris','Phasianidae','80-100 см','7-12 кг','6-9 років','Франція','Всеїдні','Темне оперення, витривалість, м\'ясна продуктивність','Вільний вигул, доступ до водойм','Природним шляхом або інкубаторами','М\'ясо','https://agromega.in.ua/imgproxy/gFS-Nf5pxB7S34T6o41pi4z7HH2AgkDLD56ovAfXk1w/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9EaW5kb25kdUdlcnMuanBn.webp','Жерська індичка - старовинна порода чорних індиків, виведена у Франції. Ця порода дуже рідкісна і знаходиться під загрозою зникнення. Вони найважчі з усіх французьких індиків і відомі своїм елегантним, красивим виглядом.\n\nПро історію чи конкретне походження цієї породи нічого не відомо. Однак вважається, що ці чорні індики, як і більшість інших чорних порід, були завезені до Франції єзуїтами на початку 16 століття, і поширювалися дворянством і церквою. Свою назву він отримав від місця походження – регіону Жер («департамент») у Франції, розташованого в гірському масиві Піренеїв.  Французька Чорна Індичка - це великий птах з чорним оперенням з гарними бронзовими, зеленими та коричневими тонами на спині.',3);
INSERT INTO `animals_animal` VALUES (61,'Meleagris gallopavo','Індонезійська індичка','Птахи','Meleagris','Phasianidae','85-110 см','6-10 кг','5-7 років','Індонезія','Всеїдні','Екзотичне оперення, хороша м\'ясна продуктивність','Просторі загони, регулярний догляд','Природним шляхом','М\'ясо, декоративне використання','https://agromega.in.ua/imgproxy/W4k4eHceRxrIZF7rSL6DBcEoMwrTwHSOgLzEMo388GI/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9EaW5kb25kZVNvbG9nbmUuanBn.webp','Індонезійська індичка — декоративно-м\'ясна порода, що відрізняється яскравим зовнішнім виглядом. Індонезійські індички (також відомі як Чорна Туреччина, Солонь, Чорний Солон, Індонезія Солонь, Солонь), середня різноманітність французької Туреччини з чорним оперенням та синьо-чорними ногами. Діндон де Холен Індики - витривалі птахи з сильним яскраво-червоним черешком, великі, добре укомплектовані брязги, сильний дзьоб, яскраві очі, довга шия, артрина щільна, широка сундук. Вони хороший шар (приблизно 15 яєць).',3),(62,'Meleagris gallopavo','Наррагансеттська індичка','Птахи','Meleagris','Phasianidae','90-115 см','7-12 кг','5-8 років','США','Всеїдні','Сіре з чорним оперення, хороша м\'ясна продуктивність','Вільний вигул, просторі загони','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/7i5k6Tje3sZcabREQXtERs3O88X-8wSl-qGxLr_KJs8/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9uYXJyYWdhbnNldHRfdHVya2V5LmpwZw.webp','Наррагансеттська індичка — американська м\'ясна порода з унікальним сірим оперенням. Колірний малюнок Наррагансеттської породи індиків містить чорний, сірий, засмаглий та білий. Його малюнок схожий на бронзу, з сталевим сірим або тупий чорний, що замінює мідну бронзу. Білі пір\'я на крилах є результатом генетичної мутації, яка видаляє бронзове забарвлення і не відомий за межами Сполучених Штатів. Дзьоб Narragansett рожевого кольору, його голова від червоного до синюватого білого кольору, а її борона чорна. Хвіст та ноги - лососевого кольору. Індички Narragansett традиційно були відомі своїм спокійним характером, з хорошими материнськими здібностями, раннім дозріванням, виробництвом яєць та відмінною якістю м\'яса. ',3),(63,'Meleagris gallopavo','Карликова Біла індичка','Птахи','Meleagris','Phasianidae','60-80 см','3-5 кг','5-7 років','Європа','Всеїдні','Маленький розмір, висока несучість','Вигул у невеликих загонах, регулярне годування','Природним шляхом або інкубаторами','Яйця, декоративне використання','https://agromega.in.ua/imgproxy/Eb2H9Ij9CywmntKrL1xY_7lJlHaZ8_wJ3KY14Y89zGM/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9NaWRnZXRXaGl0ZVR1cmtleXMuanBn.webp','Карликова Біла індичка — мініатюрна порода, що відрізняється високою несучістю і компактним розміром. Черепахи білі індики були розроблені в 1960-х роках д-ром Джорном Робертом Смітом в Університеті штату Массачусетс Амхерст. Але там не було очікуваного попиту на малих індиків, і вони не були успішними. Нарешті, вони не класифіковані як критичні для американського поголів\'я поголів\'я худоби, і вони включені в ковчег смаку, каталогізувати продукти, що знаходяться під загрозою зникнення. У 2014 році, як вважається, вимерлих білих індичок було вимерлим, приблизно 90 з них були виявлені в Алабамі. М\'які білі індички відносно доброзичливі та особливо придатні для вирощування на невеликих фермах або на задньому дворі.',3),(64,'Meleagris gallopavo','Королівські індички','Птахи','Meleagris','Phasianidae','90-110 см','8-12 кг','6-8 років','США, Європа','Всеїдні','Великий розмір, красива будова тіла, м\'ясна продуктивність','Просторі загони, доступ до води','Інкубатори або природним шляхом','М\'ясо','https://agromega.in.ua/imgproxy/cyghGTcTJe2mP_XGlk-rRPfvcc3vHz4tO_oPJgwfSxU/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9Sb3lhbFBhbG0uanBn.webp','Королівські палички Індики - це порода Туреччини, найвідоміша як іконописна птиця з унікальним виглядом, в основному біла з смужками металічного чорного кольору. Томів відзначають неагресивність, а хворих особливо хороших матерів, але вони занадто малі для комерційного використання. Theyrnare в основному зберігається як виставка птахів, або на невеликих фермах. Королівські індички-пташки - це дуже під загрозою зникнення породи. Вони знаходяться на переліку з американською охороною поголів\'я худоби. Вони також включаються в \"Ковчег смаків\" Slow Food в США, каталог спадщини харчових продуктів, що знаходяться в небезпеці вимирання. І Австралія та США обидва повідомляють цю породу як \"загрозу\". У Європі індичка з подібною забарвленням іноді називається \"Кролвітцер\", \"Пюс\" або \"Чорні\" білими.',3),(65,'Meleagris gallopavo','Ронкьерська індичка','Птахи','Meleagris','Phasianidae','80-100 см','7-10 кг','6-9 років','Франція','Всеїдні','Висока м\'ясна продуктивність, темне оперення','Просторі пасовища, доступ до водойм','Природним шляхом або інкубаторами','М\'ясо','https://agromega.in.ua/imgproxy/3s5mbTEZshQbMyPp0YCKL5MIdBaOBn6O1kJbEpiW--4/rs:fit:1520:800:f:0/aHR0cHM6Ly9hZ3JvbWVnYS5hbXMzLmNkbi5kaWdpdGFsb2NlYW5zcGFjZXMuY29tL21lZGlhL2ltYWdlcy9Sb25xdWlyZXNfdHVya2V5LmpwZw.webp','Ронкьерcька (Ronquières) - дуже стара бельгійська порода, яка вже була зображена на картинах різних майстрів у 17 столітті. На півночі Ено, регіон Ронкьер, протягом п\'яти століть традиційно розводять багатьох індиків. Наприкінці минулого століття у заводчика не рідко можна було знайти 500 - 600 індиків. Навіть у \"маленького фермера\" часто було 150 птахів. Ronquières - досить легка порода індиків з білими ногами і синюватою головою. На даний момент ця індичка визнана у п\'яти кольорових різновидах: куріпка, блідий, горностай, жовтоплеча та біла. Ronquières - справжній ландрас. Це загартовані птахи, які здатні збирати їжу на вигулі. Індички добре розмножуються і є хорошими мамами для пташенят. На даний м